import java.util.*;

[[public|public]] [[class|class]] CollectionsDemo {
    [[public|public]] static void main(String[] args) {
        // [[arraylist|arraylist]] with [[generics|generics]]
        [[list|list]]<String> names = new [[arraylist|arraylist]]<>();
        names.add("Alice");
        names.add("Bob");
        names.add("Charlie");

        // [[hashmap|hashmap]] with [[generics|generics]]
        [[map|map]]<String, Integer> scores = new [[hashmap|hashmap]]<>();
        scores.put("Alice", 95);
        scores.put("Bob", 87);

        // Iterate
        for (String name : names) {
            System.out.println(name + ": " + scores.getOrDefault(name, 0));
        }

        // Sort with [[comparator|comparator]]
        names.sort((a, b) -> b.compareTo(a));  // Descending
        System.out.println("Sorted: " + names);
    }
}
