```java
import java.io.*;
import java.util.*;

[[public|public]] [[class|class]] StudentFileIO {
    [[public|public]] static void main(String[] args) {
        [[list|list]]<Student> students = [[list|list]].of(
            new Student("Alice", 20, 4.5),
            new Student("Bob", 22, 3.8)
        );

        // Write
        try ([[printwriter|printwriter]] pw = new [[printwriter|printwriter]]("students.txt")) {
            for (Student s : students) {
                pw.println(s.getName() + "," + s.getAge() + "," + s.getGpa());
            }
        } catch (IOException e) { e.printStackTrace(); }

        // Read
        try ([[bufferedreader|bufferedreader]] br = new [[bufferedreader|bufferedreader]](new [[filereader|filereader]]("students.txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] parts = line.split(",");
                System.out.println(parts[0] + " - Age: " + parts[1] + " - GPA: " + parts[2]);
            }
        } catch (IOException e) { e.printStackTrace(); }
    }
}

